sys_script.script:
/**
 * Business Rule: Apollo - Validate Doctor Availability
 * Table: x_2223823_apollo_0_appointment
 * When: before
 * Order: 90 (Runs before the overlap check at Order 100)
 * Insert: true | Update: true
 * Condition: current.doctor.changes() || current.hospital.changes() || current.start_time.changes() || current.end_time.changes() || current.operation() == 'insert'
 */
(function executeRule(current, previous /*null when async*/) {

    var availEngine = new x_2223823_apollo_0.ApolloDoctorAvailability();
    var result = availEngine.validateDoctor(current);

    if (!result.valid) {
        // Display clear error reason why the appointment cannot be created
        gs.addErrorMessage(result.message);

        // If slot recommendations were generated, display them cleanly to the user/receptionist
        if (result.availableSlotsMsg) {
            gs.addInfoMessage(result.availableSlotsMsg);
        }

        // Abort the database save action
        current.setAbortAction(true);
    }

})(current, previous);
